export const runSqlImport = mutation({
  args: {},
  handler: async (ctx) => {
    const results: Record<string, unknown> = {};

    const existingMovies = await ctx.db.query("movies").collect();
    const existingSeries = await ctx.db.query("series").collect();

    const movieNames = new Set(existingMovies.map((m) => m.name));
    let moviesInserted = 0;
    for (const movie of SQL_MOVIES) {
      if (!movieNames.has(movie.name)) {
        await ctx.db.insert("movies", movie);
        moviesInserted++;
      }
    }
    results.movies = { total: SQL_MOVIES.length, inserted: moviesInserted, skipped: SQL_MOVIES.length - moviesInserted };

    const seriesKeys = new Set(existingSeries.map((s) => s.name + "|" + (s.season || 1)));
    let seriesInserted = 0;
    for (const serie of SQL_SERIES) {
      const key = serie.name + "|" + (serie.season || 1);
      if (!seriesKeys.has(key)) {
        await ctx.db.insert("series", serie);
        seriesInserted++;
      }
    }
    results.series = { total: SQL_SERIES.length, inserted: seriesInserted, skipped: SQL_SERIES.length - seriesInserted };

    return results;
  },
});
